mapper.update:
UPDATE shared_essay
SET version_ids = #{versionIds},
    latest_added_version_ids = #{latestAddedVersionIds},
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT q.id AS questionId, q.sort_order AS questionOrder, q.question_text AS questionText, v.id AS versionId, v.version_name AS versionName, v.body AS body FROM essay_versions v JOIN essay_questions q ON q.id = v.question_id WHERE v.id IN
#{id}
ORDER BY q.sort_order ASC
